using System;
using System.Configuration;
using System.Data.SqlClient;
using Customization;

namespace Aesthetik.SchemaFix
{
    public class AesthetikSchemaFixInstallerV3 : CustomizationPlugin
    {
        public override void UpdateDatabase()
        {
            try
            {
                var cs = ConfigurationManager.ConnectionStrings["ProjectX"];
                if (cs == null)
                {
                    WriteLog("[AesthetikSchemaFixV3] No ProjectX connection string found, trying alternatives...");
                    foreach (ConnectionStringSettings s in ConfigurationManager.ConnectionStrings)
                    {
                        WriteLog("[AesthetikSchemaFixV3] Found connection: " + s.Name);
                    }
                    return;
                }
                string connStr = cs.ConnectionString;
                WriteLog("[AesthetikSchemaFixV3] Using System.Data.SqlClient with connection: " + cs.Name);

                using (var conn = new SqlConnection(connStr))
                {
                    conn.Open();
                    WriteLog("[AesthetikSchemaFixV3] Connection opened successfully");
                    string[] statements = new[]
                    {
                        "IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('SOOrder') AND name = 'UsrComplianceHold') ALTER TABLE SOOrder ADD UsrComplianceHold bit NULL",
                        "IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('SOOrder') AND name = 'UsrComplianceHoldReason') ALTER TABLE SOOrder ADD UsrComplianceHoldReason nvarchar(500) NULL",
                        "IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('BAccount') AND name = 'UsrDisablePayLink') ALTER TABLE BAccount ADD UsrDisablePayLink bit NULL",
                        "IF NOT EXISTS (SELECT 1 FROM sys.views WHERE name = 'UsrAuditTrailView') EXEC('CREATE VIEW UsrAuditTrailView AS SELECT CompanyID, BatchID, ChangeID, ScreenID, UserID, ChangeDate, Operation, TableName, CombinedKey, ModifiedFields FROM AuditHistory')",
                        "IF NOT EXISTS (SELECT 1 FROM sys.tables WHERE name = 'UsrAuditSnapshot') EXEC('CREATE TABLE UsrAuditSnapshot (CompanyID INT NOT NULL DEFAULT 2, SnapshotID INT IDENTITY(1,1) NOT NULL, BatchID BIGINT NULL, ChangeID BIGINT NULL, ScreenID CHAR(8) NULL, UserID UNIQUEIDENTIFIER NULL, UserName NVARCHAR(256) NULL, ChangeDate DATETIME NULL, Operation CHAR(1) NULL, TableName VARCHAR(100) NULL, CombinedKey NVARCHAR(796) NULL, ModifiedFields NVARCHAR(MAX) NULL, SnapshotDate DATETIME NOT NULL DEFAULT GETUTCDATE(), tstamp TIMESTAMP NOT NULL, CONSTRAINT PK_UsrAuditSnapshot PRIMARY KEY (CompanyID, SnapshotID))')",
                        "IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'IX_UsrAuditSnapshot_ChangeDate') EXEC('CREATE INDEX IX_UsrAuditSnapshot_ChangeDate ON UsrAuditSnapshot (CompanyID, ChangeDate DESC)')"
                    };
                    foreach (string sql in statements)
                    {
                        using (var cmd = conn.CreateCommand())
                        {
                            cmd.CommandText = sql;
                            cmd.ExecuteNonQuery();
                        }
                        string col = sql.Substring(sql.IndexOf("name = '") + 8);
                        col = col.Substring(0, col.IndexOf("'"));
                        WriteLog("[AesthetikSchemaFixV3] OK: " + col);
                    }
                }
                WriteLog("[AesthetikSchemaFixV3] All columns created successfully");
            }
            catch (Exception ex)
            {
                WriteLog("[AesthetikSchemaFixV3] ERROR: " + ex.GetType().FullName + ": " + ex.Message);
                if (ex.InnerException != null)
                    WriteLog("[AesthetikSchemaFixV3] Inner: " + ex.InnerException.Message);
            }
        }
    }
}

using System;
using System.Configuration;
using System.Data.SqlClient;
using Customization;

namespace StudioB.Setup
{
    public class StudioBAuditGISetup : CustomizationPlugin
    {
        public override void UpdateDatabase()
        {
            CleanupBrokenGI();
            RefreshAuditSnapshot();
            CreateOrUpdateGI();
        }

        private void CleanupBrokenGI()
        {
            try
            {
                var cs = ConfigurationManager.ConnectionStrings["ProjectX"];
                if (cs == null) return;
                using (var conn = new SqlConnection(cs.ConnectionString))
                {
                    conn.Open();
                    int cid = GetCompanyId(conn);
                    if (cid == 0) return;

                    string designId = null;
                    using (var cmd = new SqlCommand(
                        "SELECT TOP 1 CONVERT(NVARCHAR(36), DesignID) FROM GIDesign WHERE Name = 'StudioBAuditTrail' AND CompanyID = @cid", conn))
                    {
                        cmd.Parameters.AddWithValue("@cid", cid);
                        var r = cmd.ExecuteScalar();
                        if (r != null && r != DBNull.Value) designId = r.ToString();
                    }
                    if (designId != null)
                    {
                        foreach (var tbl in new[] { "GIResult", "GISort", "GIGroupBy", "GIWhere", "GIOn", "GIFilter", "GITable", "GIDesign" })
                        {
                            using (var cmd = new SqlCommand("DELETE FROM " + tbl + " WHERE DesignID = @did AND CompanyID = @cid", conn))
                            {
                                cmd.Parameters.AddWithValue("@did", designId);
                                cmd.Parameters.AddWithValue("@cid", cid);
                                cmd.ExecuteNonQuery();
                            }
                        }
                        WriteLog("[AuditSetup] Deleted old GI");
                    }
                }
            }
            catch (Exception ex) { WriteLog("[AuditSetup] GI cleanup: " + ex.Message); }
        }

        private void RefreshAuditSnapshot()
        {
            try
            {
                var cs = ConfigurationManager.ConnectionStrings["ProjectX"];
                if (cs == null) return;
                using (var conn = new SqlConnection(cs.ConnectionString))
                {
                    conn.Open();
                    int cid = GetCompanyId(conn);

                    // Delete old snapshot rows (older than 30 days)
                    using (var cmd = new SqlCommand(
                        "DELETE FROM UsrAuditSnapshot WHERE CompanyID = @cid AND ChangeDate < @cutoff", conn))
                    {
                        cmd.Parameters.AddWithValue("@cid", cid);
                        cmd.Parameters.AddWithValue("@cutoff", DateTime.UtcNow.AddDays(-30));
                        int deleted = cmd.ExecuteNonQuery();
                        if (deleted > 0) WriteLog("[AuditSetup] Pruned " + deleted + " old snapshot rows");
                    }

                    // Find the most recent ChangeDate in snapshot to avoid duplicates
                    DateTime since = DateTime.UtcNow.AddDays(-7);
                    using (var cmd = new SqlCommand(
                        "SELECT MAX(ChangeDate) FROM UsrAuditSnapshot WHERE CompanyID = @cid", conn))
                    {
                        cmd.Parameters.AddWithValue("@cid", cid);
                        var r = cmd.ExecuteScalar();
                        if (r != null && r != DBNull.Value)
                        {
                            DateTime lastDate = (DateTime)r;
                            if (lastDate > since) since = lastDate;
                        }
                    }

                    // INSERT new audit rows from AuditHistory via the VIEW
                    using (var cmd = new SqlCommand(@"
                        INSERT INTO UsrAuditSnapshot
                            (CompanyID, BatchID, ChangeID, ScreenID, UserID, UserName,
                             ChangeDate, Operation, TableName, CombinedKey, ModifiedFields)
                        SELECT
                            @cid, a.BatchID, a.ChangeID, a.ScreenID, a.UserID, u.Username,
                            a.ChangeDate, a.Operation, a.TableName, a.CombinedKey, a.ModifiedFields
                        FROM UsrAuditTrailView a
                        LEFT JOIN Users u ON a.UserID = u.PKID
                        WHERE a.ChangeDate > @since
                        AND NOT EXISTS (
                            SELECT 1 FROM UsrAuditSnapshot s
                            WHERE s.CompanyID = @cid AND s.BatchID = a.BatchID AND s.ChangeID = a.ChangeID
                        )
                        ORDER BY a.ChangeDate DESC", conn))
                    {
                        cmd.Parameters.AddWithValue("@cid", cid);
                        cmd.Parameters.AddWithValue("@since", since);
                        cmd.CommandTimeout = 60;
                        int inserted = cmd.ExecuteNonQuery();
                        WriteLog("[AuditSetup] Snapshot: " + inserted + " new rows (since " + since.ToString("yyyy-MM-dd HH:mm") + ")");
                    }
                }
            }
            catch (Exception ex) { WriteLog("[AuditSetup] Snapshot: " + ex.Message); }
        }

        private void CreateOrUpdateGI()
        {
            try
            {
                var cs = ConfigurationManager.ConnectionStrings["ProjectX"];
                if (cs == null) return;
                using (var conn = new SqlConnection(cs.ConnectionString))
                {
                    conn.Open();
                    int cid = GetCompanyId(conn);
                    if (cid == 0) return;

                    // Check if GI already exists
                    using (var cmd = new SqlCommand("SELECT COUNT(*) FROM GIDesign WHERE Name = 'StudioBAuditSnapshot' AND CompanyID = @cid", conn))
                    {
                        cmd.Parameters.AddWithValue("@cid", cid);
                        if ((int)cmd.ExecuteScalar() > 0) { WriteLog("[AuditSetup] GI exists"); return; }
                    }

                    // Get template
                    string tid = null;
                    using (var cmd = new SqlCommand("SELECT TOP 1 CONVERT(NVARCHAR(36), DesignID) FROM GIDesign WHERE CompanyID = @cid", conn))
                    {
                        cmd.Parameters.AddWithValue("@cid", cid);
                        var r = cmd.ExecuteScalar();
                        if (r != null && r != DBNull.Value) tid = r.ToString();
                    }
                    if (tid == null) return;

                    string newId = Guid.NewGuid().ToString();

                    // GIDesign
                    InsertFromTemplate(conn, "GIDesign", tid, newId, cid,
                        new[] { "Name", "ExposeViaOData", "ScreenID", "PageSize" },
                        new[] { "'StudioBAuditSnapshot'", "1", "'GI000000'", "200" });

                    // GITable
                    InsertFromTemplate(conn, "GITable", tid, newId, cid,
                        new[] { "Name", "Alias" },
                        new[] { "'StudioB.DAC.UsrAuditSnapshot'", "'UsrAuditSnapshot'" });

                    // GIResult — one row per field
                    string tplR = null;
                    using (var cmd = new SqlCommand("SELECT TOP 1 CONVERT(NVARCHAR(36), DesignID) FROM GIResult WHERE CompanyID = @cid", conn))
                    {
                        cmd.Parameters.AddWithValue("@cid", cid);
                        var r = cmd.ExecuteScalar();
                        if (r != null && r != DBNull.Value) tplR = r.ToString();
                    }
                    if (tplR == null) return;

                    string[] fields = { "SnapshotID", "ScreenID", "UserName", "ChangeDate", "Operation", "TableName", "CombinedKey", "ModifiedFields" };
                    for (int i = 0; i < fields.Length; i++)
                    {
                        InsertFromTemplate(conn, "GIResult", tplR, newId, cid,
                            new[] { "LineNbr", "IsActive", "ObjectName", "Field", "SchemaField", "SortOrder", "IsVisible", "Width", "Caption", "QuickFilter", "FastFilter", "DefaultNav" },
                            new[] { (i+1).ToString(), "1", "'UsrAuditSnapshot'", "'" + fields[i] + "'", "NULL", (i+1).ToString(), "1", "120", "'" + fields[i] + "'", "0", "0", "0" });
                    }

                    WriteLog("[AuditSetup] GI StudioBAuditSnapshot created, OData=1");
                }
            }
            catch (Exception ex) { WriteLog("[AuditSetup] GI: " + ex.Message); }
        }

        private void InsertFromTemplate(SqlConnection conn, string table, string templateId, string newId, int cid,
            string[] overrideNames, string[] overrideValues)
        {
            var cols = new System.Collections.Generic.List<string>();
            using (var cmd = new SqlCommand(@"SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS
                WHERE TABLE_NAME = @t AND COLUMN_NAME NOT IN ('DeletedDatabaseRecord','Tstamp')
                AND DATA_TYPE NOT IN ('timestamp') ORDER BY ORDINAL_POSITION", conn))
            {
                cmd.Parameters.AddWithValue("@t", table);
                using (var reader = cmd.ExecuteReader()) { while (reader.Read()) cols.Add(reader.GetString(0)); }
            }

            var overrides = new System.Collections.Generic.Dictionary<string, string>();
            for (int i = 0; i < overrideNames.Length; i++) overrides[overrideNames[i]] = overrideValues[i];
            overrides["DesignID"] = "'" + newId + "'";
            overrides["NoteID"] = "NEWID()";
            overrides["RowID"] = "NEWID()";
            overrides["CreatedDateTime"] = "GETUTCDATE()";
            overrides["LastModifiedDateTime"] = "GETUTCDATE()";

            var selectParts = new System.Collections.Generic.List<string>();
            foreach (var col in cols)
                selectParts.Add(overrides.ContainsKey(col) ? overrides[col] : "[" + col + "]");

            using (var cmd = new SqlCommand(
                "INSERT INTO " + table + " ([" + string.Join("],[", cols) + "]) SELECT TOP 1 " +
                string.Join(",", selectParts) + " FROM " + table + " WHERE DesignID = @tid AND CompanyID = @cid", conn))
            {
                cmd.Parameters.AddWithValue("@tid", templateId);
                cmd.Parameters.AddWithValue("@cid", cid);
                cmd.ExecuteNonQuery();
            }
        }

        private int GetCompanyId(SqlConnection conn)
        {
            using (var cmd = new SqlCommand("SELECT TOP 1 CompanyID FROM GIDesign WHERE CompanyID > 0", conn))
            {
                var r = cmd.ExecuteScalar();
                return r != null ? (int)r : 0;
            }
        }
    }
}

using System;
using PX.Data;
using PX.Data.BQL;

namespace StudioB.DAC
{
    [Serializable]
    [PXCacheName("Audit Snapshot")]
    public class UsrAuditSnapshot : PXBqlTable, IBqlTable
    {
        #region SnapshotID
        public abstract class snapshotID : BqlInt.Field<snapshotID> { }
        [PXDBIdentity(IsKey = true)]
        [PXUIField(DisplayName = "Snapshot ID")]
        public virtual int? SnapshotID { get; set; }
        #endregion

        #region BatchID
        public abstract class batchID : BqlLong.Field<batchID> { }
        [PXDBLong]
        [PXUIField(DisplayName = "Batch ID")]
        public virtual long? BatchID { get; set; }
        #endregion

        #region ChangeID
        public abstract class changeID : BqlLong.Field<changeID> { }
        [PXDBLong]
        [PXUIField(DisplayName = "Change ID")]
        public virtual long? ChangeID { get; set; }
        #endregion

        #region ScreenID
        public abstract class screenID : BqlString.Field<screenID> { }
        [PXDBString(8, IsFixed = true)]
        [PXUIField(DisplayName = "Screen ID")]
        public virtual string ScreenID { get; set; }
        #endregion

        #region UserID
        public abstract class userID : BqlGuid.Field<userID> { }
        [PXDBGuid]
        [PXUIField(DisplayName = "User ID")]
        public virtual Guid? UserID { get; set; }
        #endregion

        #region UserName
        public abstract class userName : BqlString.Field<userName> { }
        [PXDBString(256)]
        [PXUIField(DisplayName = "User Name")]
        public virtual string UserName { get; set; }
        #endregion

        #region ChangeDate
        public abstract class changeDate : BqlDateTime.Field<changeDate> { }
        [PXDBDate(PreserveTime = true)]
        [PXUIField(DisplayName = "Change Date")]
        public virtual DateTime? ChangeDate { get; set; }
        #endregion

        #region Operation
        public abstract class operation : BqlString.Field<operation> { }
        [PXDBString(1, IsFixed = true)]
        [PXUIField(DisplayName = "Operation")]
        public virtual string Operation { get; set; }
        #endregion

        #region TableName
        public abstract class tableName : BqlString.Field<tableName> { }
        [PXDBString(100)]
        [PXUIField(DisplayName = "Table Name")]
        public virtual string TableName { get; set; }
        #endregion

        #region CombinedKey
        public abstract class combinedKey : BqlString.Field<combinedKey> { }
        [PXDBString(796)]
        [PXUIField(DisplayName = "Combined Key")]
        public virtual string CombinedKey { get; set; }
        #endregion

        #region ModifiedFields
        public abstract class modifiedFields : BqlString.Field<modifiedFields> { }
        [PXDBString(IsUnicode = true)]
        [PXUIField(DisplayName = "Modified Fields")]
        public virtual string ModifiedFields { get; set; }
        #endregion

        #region SnapshotDate
        public abstract class snapshotDate : BqlDateTime.Field<snapshotDate> { }
        [PXDBDate(PreserveTime = true)]
        [PXUIField(DisplayName = "Snapshot Date")]
        public virtual DateTime? SnapshotDate { get; set; }
        #endregion

        #region Tstamp
        public abstract class tstamp : IBqlField { }
        [PXDBTimestamp]
        public virtual byte[] Tstamp { get; set; }
        #endregion
    }
}

using System;
using System.Reflection;
using Customization;

namespace StudioB.Diagnostics
{
    /// <summary>
    /// One-time diagnostic plugin: enumerates all properties and nested BQL field
    /// classes on PX.SM.AuditHistory via reflection. Output appears in publish log
    /// as [information] entries. Remove after field names are discovered.
    /// </summary>
    public class AuditHistoryReflector : CustomizationPlugin
    {
        public override void UpdateDatabase()
        {
            // Publish log truncates per-plugin entries. Concat everything into minimal WriteLog calls.
            try
            {
                var dacType = typeof(PX.SM.AuditHistory);

                // 1. ALL declared properties in ONE log entry
                var props = dacType.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly);
                var propList = new System.Collections.Generic.List<string>();
                foreach (var prop in props)
                {
                    string pxAttr = "";
                    try
                    {
                        foreach (var a in prop.GetCustomAttributes(false))
                        {
                            var n = a.GetType().Name;
                            if (n.StartsWith("PXDB") || n.StartsWith("PXString") || n.StartsWith("PXInt") || n.StartsWith("PXDate") || n.StartsWith("PXBool") || n.StartsWith("PXDecimal") || n.StartsWith("PXGuid") || n.StartsWith("PXLong"))
                                pxAttr = "[" + n + "]";
                        }
                    }
                    catch { }
                    propList.Add(prop.Name + "(" + prop.PropertyType.Name + ")" + pxAttr);
                }
                WriteLog("[AuditReflector] PROPS(" + props.Length + "): " + string.Join(" | ", propList));

                // 2. ALL nested BQL field classes in ONE log entry
                var nested = dacType.GetNestedTypes(BindingFlags.Public | BindingFlags.NonPublic);
                var nestedList = new System.Collections.Generic.List<string>();
                foreach (var nt in nested) nestedList.Add(nt.Name);
                WriteLog("[AuditReflector] NESTED(" + nested.Length + "): " + string.Join(" | ", nestedList));

                // 3. Also check the actual DB table by querying sys.columns
                var cs = System.Configuration.ConfigurationManager.ConnectionStrings["ProjectX"];
                if (cs != null)
                {
                    using (var conn = new System.Data.SqlClient.SqlConnection(cs.ConnectionString))
                    {
                        conn.Open();
                        // Try common audit table names
                        foreach (var tbl in new[] { "AuditHistory", "SMHistory", "ARAuditHistory", "AuditTrail", "SM205530" })
                        {
                            using (var cmd = conn.CreateCommand())
                            {
                                cmd.CommandText = "SELECT COUNT(*) FROM sys.tables WHERE name = @t";
                                cmd.Parameters.AddWithValue("@t", tbl);
                                var cnt = (int)cmd.ExecuteScalar();
                                if (cnt > 0)
                                {
                                    // Get all columns
                                    var colList = new System.Collections.Generic.List<string>();
                                    using (var cmd2 = conn.CreateCommand())
                                    {
                                        cmd2.CommandText = "SELECT c.name + '(' + t.name + ',' + CAST(c.max_length AS VARCHAR) + ')' FROM sys.columns c JOIN sys.types t ON c.user_type_id = t.user_type_id WHERE c.object_id = OBJECT_ID(@t) ORDER BY c.column_id";
                                        cmd2.Parameters.AddWithValue("@t", tbl);
                                        using (var reader = cmd2.ExecuteReader())
                                        {
                                            while (reader.Read()) colList.Add(reader.GetString(0));
                                        }
                                    }
                                    WriteLog("[AuditReflector] TABLE " + tbl + "(" + colList.Count + "): " + string.Join(" | ", colList));
                                }
                            }
                        }

                        // Also try: find tables with "Audit" in the name
                        var auditTables = new System.Collections.Generic.List<string>();
                        using (var cmd = conn.CreateCommand())
                        {
                            cmd.CommandText = "SELECT name FROM sys.tables WHERE name LIKE '%Audit%' OR name LIKE '%audit%' ORDER BY name";
                            using (var reader = cmd.ExecuteReader())
                            {
                                while (reader.Read()) auditTables.Add(reader.GetString(0));
                            }
                        }
                        WriteLog("[AuditReflector] AUDIT_TABLES: " + string.Join(" | ", auditTables));

                        // Check AuditHistory table row count
                        try
                        {
                            using (var cmd = conn.CreateCommand())
                            {
                                cmd.CommandText = "SELECT TOP 1 * FROM AuditHistory";
                                using (var reader = cmd.ExecuteReader())
                                {
                                    var colNames = new System.Collections.Generic.List<string>();
                                    for (int i = 0; i < reader.FieldCount; i++)
                                        colNames.Add(reader.GetName(i) + "(" + reader.GetFieldType(i).Name + ")");
                                    WriteLog("[AuditReflector] AuditHistory_READER_COLS: " + string.Join(" | ", colNames));
                                }
                            }
                        }
                        catch (Exception ex2)
                        {
                            WriteLog("[AuditReflector] AuditHistory_QUERY_ERR: " + ex2.Message);
                        }
                    }
                }

                // 4. Base type
                WriteLog("[AuditReflector] BASE: " + dacType.BaseType?.FullName + " ASM: " + dacType.Assembly.GetName().Name);

                // 5. GI diagnostics — check StudioBAuditSnapshot GI + data source names of working OData GIs
                if (cs != null)
                {
                    using (var conn2 = new System.Data.SqlClient.SqlConnection(cs.ConnectionString))
                    {
                        conn2.Open();
                        // Check UsrAuditSnapshot table exists + row count
                        try
                        {
                            using (var cmd = conn2.CreateCommand())
                            {
                                cmd.CommandText = "SELECT COUNT(*) FROM UsrAuditSnapshot";
                                var cnt = cmd.ExecuteScalar();
                                WriteLog("[AuditReflector] UsrAuditSnapshot rows: " + cnt);
                            }
                        }
                        catch (Exception ex3) { WriteLog("[AuditReflector] UsrAuditSnapshot: " + ex3.Message); }

                        // Check GI data source names for OData-enabled GIs
                        var giInfo = new System.Collections.Generic.List<string>();
                        using (var cmd = conn2.CreateCommand())
                        {
                            cmd.CommandText = @"SELECT TOP 5 d.Name, t.Name AS DataSource, t.Alias
                                FROM GIDesign d JOIN GITable t ON d.DesignID = t.DesignID AND d.CompanyID = t.CompanyID
                                WHERE d.ExposeViaOData = 1 AND d.CompanyID > 0
                                ORDER BY d.Name";
                            using (var reader = cmd.ExecuteReader())
                            {
                                while (reader.Read())
                                    giInfo.Add(reader.GetString(0) + "=" + reader.GetString(1) + "/" + reader.GetString(2));
                            }
                        }
                        WriteLog("[AuditReflector] ODATA_GIS: " + string.Join(" | ", giInfo));

                        // Check our GI specifically
                        using (var cmd = conn2.CreateCommand())
                        {
                            cmd.CommandText = @"SELECT d.Name, d.ExposeViaOData, t.Name AS DataSource, t.Alias,
                                (SELECT COUNT(*) FROM GIResult r WHERE r.DesignID = d.DesignID AND r.CompanyID = d.CompanyID) AS ResultCols
                                FROM GIDesign d LEFT JOIN GITable t ON d.DesignID = t.DesignID AND d.CompanyID = t.CompanyID
                                WHERE d.Name = 'StudioBAuditSnapshot' AND d.CompanyID > 0";
                            using (var reader = cmd.ExecuteReader())
                            {
                                if (reader.Read())
                                    WriteLog("[AuditReflector] OUR_GI: " + reader.GetString(0) + " OData=" + reader.GetInt32(1) + " Src=" + (reader.IsDBNull(2) ? "NULL" : reader.GetString(2)) + " Alias=" + (reader.IsDBNull(3) ? "NULL" : reader.GetString(3)) + " Cols=" + reader.GetInt32(4));
                                else
                                    WriteLog("[AuditReflector] OUR_GI: NOT FOUND");
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                WriteLog("[AuditReflector] FATAL: " + ex.GetType().FullName + ": " + ex.Message);
            }
        }
    }
}
